PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?baseCelex ?work ?date ?inForce ?versionCelex ?versionDate WHERE {
 VALUES ?baseCelex { "32022R2554"^^xsd:string "32013R0575"^^xsd:string "32013L0036"^^xsd:string "32014L0065"^^xsd:string "32014R0600"^^xsd:string "32015L0849"^^xsd:string "32012R0648"^^xsd:string "32009L0138"^^xsd:string "32019R2033"^^xsd:string "32019L2034"^^xsd:string "32011L0061"^^xsd:string "32009L0065"^^xsd:string "32015L2366"^^xsd:string "32009R1060"^^xsd:string "32014R0909"^^xsd:string "32016R1011"^^xsd:string "32010R1093"^^xsd:string "32014R0806"^^xsd:string "32019R1238"^^xsd:string "32002R1606"^^xsd:string "32006L0048"^^xsd:string "32015R0035"^^xsd:string "32002L0087"^^xsd:string "32006L0049"^^xsd:string }
 ?work cdm:resource_legal_id_celex ?baseCelex .
 OPTIONAL { ?work cdm:work_date_document ?date . }
 OPTIONAL { ?work cdm:resource_legal_in-force ?inForce . }
 OPTIONAL { ?version cdm:act_consolidated_based_on_resource_legal ?work ; cdm:act_consolidated_date ?versionDate ; cdm:resource_legal_id_celex ?versionCelex . }
} ORDER BY ?baseCelex DESC(?versionDate) LIMIT 10000
